437				t.Errorf("case %d: status = %d, want 400; body %s", i, rec.Code, rec.Body.String())
438				continue
439			}
440			expectErrorCode(t, rec, http.StatusBadRequest, "InvalidPlacementInputError")
441		}
442	
443		// Rejected input must not have been stored.
444		list := doRequest(t, h, http.MethodGet, "/v1/placements?namespace=ns", "")
445		if items := decodeBody(t, list)["items"].([]any); len(items) != 0 {
446			t.Fatalf("invalid bodies stored %d records", len(items))
447		}
448	}
449	
450	func TestBoundaryValuesAccepted(t *testing.T) {
451		_, h := newTestRouter(t)
452		body := `{
453		  "namespace": "ns", "name": "job", "queue": "q",
454		  "priority": 2147483647,
455		  "resources": {"cpu": 9223372036854775807, "memory": 1},
456		  "nodes": [{"name": "n", "cpu": 0, "memory": 0, "labels": {}}]
457		}`
458		if rec := postPlacement(t, h, body); rec.Code != http.StatusCreated {
459			t.Fatalf("max int values rejected: %d %s", rec.Code, rec.Body.String())
460		}
461		body2 := `{
462		  "namespace": "ns2", "name": "job", "queue": "q",
463		  "priority": -2147483648,
464		  "resources": {"cpu": 1, "memory": 1},
465		  "nodes": [{"name": "n", "cpu": 0, "memory": 0}]
466		}`
467		if rec := postPlacement(t, h, body2); rec.Code != http.StatusCreated {
468			t.Fatalf("min int32 priority rejected: %d %s", rec.Code, rec.Body.String())
469		}
470	}
471	
472	func TestStorageFailureReturns503(t *testing.T) {
473		st, h := newTestRouter(t)
474		if err := st.Close(); err != nil {
475			t.Fatalf("close: %v", err)
476		}
477		rec := postPlacement(t, h, validBody)
478		expectErrorCode(t, rec, http.StatusServiceUnavailable, "storage_unavailable")
479		if bytes.Contains(rec.Body.Bytes(), []byte("SQLITE")) || bytes.Contains(rec.Body.Bytes(), []byte(".go")) {
480			t.Fatalf("503 body leaks internals: %s", rec.Body.String())
481		}
482	}
483	
484	func TestRecordsSurviveReopen(t *testing.T) {
485		dir := t.TempDir()
486		path := filepath.Join(dir, "service.db")
487	
488		st, err := store.Open(path)
489		if err != nil {
490			t.Fatalf("open: %v", err)
491		}
492		h := NewRouter(st)
493		if rec := postPlacement(t, h, validBody); rec.Code != http.StatusCreated {
494			t.Fatalf("create: %d %s", rec.Code, rec.Body.String())
495		}
496		if err := st.Close(); err != nil {
497			t.Fatalf("close: %v", err)
498		}
499	
500		st2, err := store.Open(path)
501		if err != nil {
502			t.Fatalf("reopen: %v", err)
503		}
504		defer st2.Close()
505		h2 := NewRouter(st2)
506		rec := doRequest(t, h2, http.MethodGet, "/v1/placements?namespace=team-a&name=job-1", "")
507		if rec.Code != http.StatusOK {
508			t.Fatalf("get after reopen = %d: %s", rec.Code, rec.Body.String())
509		}
510		if got := decodeBody(t, rec); got["status"] != "placed" || got["node"] != "node-a" {
511			t.Fatalf("record changed across reopen: %s", rec.Body.String())
512		}
513	}
