	if err != nil {
		t.Fatalf("reopen: %v", err)
	}
	defer st2.Close()
	h2 := NewRouter(st2)
	rec := doRequest(t, h2, http.MethodGet, "/v1/placements?namespace=team-a&name=job-1", "")
	if rec.Code != http.StatusOK {
		t.Fatalf("get after reopen = %d: %s", rec.Code, rec.Body.String())
