// readMembers walks the members of the object dec is positioned inside and
// applies the single shared structural rule. json.Decoder delivers member
// names already unescaped, so comparison is done on the resulting name and
// escape-only spellings collapse to one key. This is the only place in the
// parser where unknown- and duplicate-member rejection is defined.
func readMembers(dec *json.Decoder, allowed map[string]bool, handle memberHandler) error {
	seen := map[string]bool{}
