		return nil, ErrInvalidPlacementInput
	}
	if d, ok := tok.(json.Delim); !ok || d != '[' {
		return nil, ErrInvalidPlacementInput
	}

	nodes := []store.Node{}
	names := map[string]bool{}
	for dec.More() {
		var elem json.RawMessage
		if err := dec.Decode(&elem); err != nil {
			return nil, ErrInvalidPlacementInput
		}
		node, err := parseNode(elem)
		if err != nil {
			return nil, err
		}
		if names[node.Name] {
			return nil, ErrInvalidPlacementInput
		}
		names[node.Name] = true
		nodes = append(nodes, node)
	}
	if _, err := dec.Token(); err != nil {
		return nil, ErrInvalidPlacementInput // closing ']'
	}
	return nodes, nil
}

// parseNode parses one candidate: the shared object rule guards its members,
// while this function owns only the node-specific required fields, ranges
// and the labels default.
func parseNode(raw json.RawMessage) (store.Node, error) {
	var n store.Node
	present := map[string]bool{}
	err := readStrictObject(raw, nodeFields, func(key string, value json.RawMessage) error {
		switch key {
		case "name":
			s, err := parseTrimmedString(value)
			if err != nil {
				return err
			}
			n.Name = s
		case "cpu":
			v, err := parseBoundedInt(value, 64)
			if err != nil || v < 0 {
				return ErrInvalidPlacementInput
			}
			n.CPU = v
		case "memory":
			v, err := parseBoundedInt(value, 64)
			if err != nil || v < 0 {
				return ErrInvalidPlacementInput
			}
			n.Memory = v
		case "labels":
			m, err := parseStringMap(value)
			if err != nil {
				return err
			}
			n.Labels = m
		}
		present[key] = true
		return nil
	})
	if err != nil {
		return store.Node{}, err
	}
	for _, required := range []string{"name", "cpu", "memory"} {
		if !present[required] {
			return store.Node{}, ErrInvalidPlacementInput
		}
	}
	if n.Labels == nil {
		n.Labels = map[string]string{}
	}
	return n, nil
