33	//     field handler for its business-specific type and range checks,
34	//   - an unknown member name is rejected,
35	//   - a repeated member name is rejected even when the two spellings differ
36	//     only by JSON escaping (e.g. "name" and "name"), so a duplicate is
37	//     never silently overwritten by the later value.
38	//
39	// readStrictObject adds the one remaining shared requirement: the value must
40	// be an object (never null, an array or a scalar). Per-field business limits
41	// (non-empty untrimmed identifiers, bounded integers, positivity) live only
42	// in the individual field handlers.
43	// ---------------------------------------------------------------------------
44	
45	var topLevelFields = map[string]bool{
46		"namespace": true,
47		"name":      true,
48		"queue":     true,
49		"priority":  true,
50		"resources": true,
51		"selector":  true,
52		"nodes":     true,
53	}
