58		"name":   true,
59		"cpu":    true,
60		"memory": true,
61		"labels": true,
62	}
63	
64	// memberHandler validates one decoded object member and applies its business
65	// rule. A nil allowed map means arbitrary member names are accepted.
66	type memberHandler func(key string, value json.RawMessage) error
67	
68	// readStrictObject enforces the shared object rule on a standalone JSON
69	// value: it must be an object, its member names must be in allowed (when
70	// allowed is non-nil), no member may repeat, and every member is passed to
71	// handle for its field-specific checks. It returns the set of member names
72	// the object actually carried, for the caller's required-field checks.
73	func readStrictObject(raw json.RawMessage, allowed map[string]bool, handle memberHandler) (map[string]bool, error) {
74		dec := json.NewDecoder(bytes.NewReader(raw))
75		tok, err := dec.Token()
76		if err != nil {
77			return nil, ErrInvalidPlacementInput
78		}
79		if d, ok := tok.(json.Delim); !ok || d != '{' {
80			return nil, ErrInvalidPlacementInput
81		}
82		return readMembers(dec, allowed, handle)
