86	// applies the single shared structural rule. json.Decoder delivers member
87	// names already unescaped, so comparison is done on the resulting name and
88	// escape-only spellings collapse to one key. It returns the set of member
89	// names seen. This is the only place in the parser where unknown- and
90	// duplicate-member rejection is defined.
91	func readMembers(dec *json.Decoder, allowed map[string]bool, handle memberHandler) (map[string]bool, error) {
92		seen := map[string]bool{}
93		for dec.More() {
94			keyTok, err := dec.Token()
95			if err != nil {
96				return nil, ErrInvalidPlacementInput
97			}
98			key, ok := keyTok.(string)
99			if !ok {
100				return nil, ErrInvalidPlacementInput
101			}
102			if allowed != nil && !allowed[key] {
103				return nil, ErrInvalidPlacementInput
104			}
105			if seen[key] {
106				return nil, ErrInvalidPlacementInput
107			}
108			seen[key] = true
109	
110			var value json.RawMessage
111			if err := dec.Decode(&value); err != nil {
112				return nil, ErrInvalidPlacementInput
113			}
114			if handle != nil {
115				if err := handle(key, value); err != nil {
116					return nil, err
117				}
118			}
119		}
120		if _, err := dec.Token(); err != nil {
121			return nil, ErrInvalidPlacementInput // closing '}'
122		}
123		return seen, nil
124	}
