130	// array stays an empty array. On any rule violation it returns nil and an
131	// error matching errors.Is(err, ErrInvalidPlacementInput).
132	func ParsePlacementInput(body []byte) (*store.Placement, error) {
133		dec := json.NewDecoder(bytes.NewReader(body))
134		dec.UseNumber()
135	
136		tok, err := dec.Token()
137		if err != nil {
138			return nil, ErrInvalidPlacementInput
139		}
