145		seen, err := readMembers(dec, topLevelFields, func(key string, raw json.RawMessage) error {
146			switch key {
147			case "namespace":
148				s, err := parseTrimmedString(raw)
149				if err != nil {
150					return err
151				}
152				p.Namespace = s
153			case "name":
154				s, err := parseTrimmedString(raw)
155				if err != nil {
156					return err
157				}
158				p.Name = s
159			case "queue":
160				s, err := parseTrimmedString(raw)
161				if err != nil {
162					return err
163				}
164				p.Queue = s
165			case "priority":
166				n, err := parseBoundedInt(raw, 32)
167				if err != nil {
168					return err
169				}
170				p.Priority = int32(n)
171			case "resources":
172				r, err := parseResources(raw)
173				if err != nil {
174					return err
175				}
176				p.Resources = r
177			case "selector":
178				m, err := parseStringMap(raw)
179				if err != nil {
180					return err
181				}
182				p.Selector = m
183			case "nodes":
184				nodes, err := parseNodes(raw)
185				if err != nil {
186					return err
187				}
188				p.Nodes = nodes
189			}
190			return nil
191		})
192		if err != nil {
193			return nil, err
194		}
195		if _, err := dec.Token(); !errors.Is(err, io.EOF) {
196			return nil, ErrInvalidPlacementInput // trailing data
197		}
198	
