347		if isNull(raw) {
348			return "", ErrInvalidPlacementInput
349		}
350		var s string
351		if err := json.Unmarshal(raw, &s); err != nil {
352			return "", ErrInvalidPlacementInput
353		}
354		return s, nil
355	}
