358	// that fits a signed integer of the given bit size (32 or 64).
359	func parseBoundedInt(raw json.RawMessage, bitSize int) (int64, error) {
360		if isNull(raw) {
361			return 0, ErrInvalidPlacementInput
362		}
363		dec := json.NewDecoder(bytes.NewReader(raw))
364		dec.UseNumber()
365		var value any
366		if err := dec.Decode(&value); err != nil {
367			return 0, ErrInvalidPlacementInput
368		}
